namespace RBX { namespace ViewNew {
ViewRbxGfx::~ViewRbxGfx()
{
    sceneManager->clear();
    renderLibScene.reset();
    materialFactory.reset();
    textureManager.reset();
    ServiceProvider::create<Lighting>(dataModel.get());
    CylinderAlongXMesh::flushCache();
    SphereMesh::flushCache();
    PBBMesh::flushCache();
    BrickMesh::flushCache();
    WedgeMesh::flushCache();
    HeadMesh::flushCache();
    TorsoMesh::flushCache();
}
void ViewRbxGfx::suppressSkybox()
{
    Lighting* lighting=ServiceProvider::create<Lighting>(static_cast<ServiceProvider*>(dataModel.get()));
    renderLibScene->presetLighting(NULL,lighting->skyParameters,lighting->ambientTop,lighting->ambientBottom);
    renderLibScene->colorClearValue=lighting->clearColor;
    G3D::Color4 shadow=lighting->shadowColor;
    dynamic_cast<RenderNew::RenderScene*>(renderLibScene.get())->shadowColor=shadow;
}
} }
